<?php
declare(strict_types=1);
require dirname(__DIR__).'/tests/harness.php';require dirname(__DIR__).'/tests/database.php';require dirname(__DIR__).'/tests/commerce-fixture.php';
use Hostider\Core\{Config,Id};use Hostider\Core\Database\Migrator;use Hostider\Commerce\Services;
$db=integrationDb();(new Migrator($db,dirname(__DIR__).'/migrations'))->migrate();$config=new Config('test','https://test.example.invalid',base64_encode(random_bytes(32)),getenv('TEST_DB_DSN'),getenv('TEST_DB_USER')?:'root',getenv('TEST_DB_PASSWORD')?:'');$s=new Services($db,$config);$users=[];for($i=0;$i<8;++$i){$users[]=commerceUser($s,'load');}$servers=[];$root=dirname(__DIR__);$env=array_merge(getenv(),['APP_ENV'=>'test','APP_URL'=>$config->url,'APP_KEY'=>$config->key,'DB_DSN'=>$config->dsn,'DB_USER'=>$config->dbUser,'DB_PASSWORD'=>$config->dbPassword]);$cookies=[];$csrf=[];
function batch(array $requests): array
{
    global $cookies,$csrf;$multi=curl_multi_init();$handles=[];$headers=[];foreach($requests as $i=>$request){$user=$request['user'];$h=curl_init('http://127.0.0.1:'.(33400+$request['server']).$request['path']);$headers[$i]=[];curl_setopt_array($h,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20,CURLOPT_HEADERFUNCTION=>function($h,string $line)use(&$headers,$i): int{$headers[$i][]=$line;return strlen($line);}]);if(isset($cookies[$user])){curl_setopt($h,CURLOPT_COOKIE,implode('; ',array_map(fn($k,$v)=>$k.'='.$v,array_keys($cookies[$user]),$cookies[$user])));}if(isset($request['data'])){curl_setopt_array($h,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($request['data'],JSON_THROW_ON_ERROR),CURLOPT_HTTPHEADER=>['Content-Type: application/json','X-CSRF-Token: '.($csrf[$user]??''),'Idempotency-Key: '.Id::uuid()]]);}curl_multi_add_handle($multi,$h);$handles[$i]=$h;}
    do{$status=curl_multi_exec($multi,$running);if($running){curl_multi_select($multi,.1);}}while($running&&$status===CURLM_OK);$out=[];foreach($handles as $i=>$h){$user=$requests[$i]['user'];$body=json_decode((string)curl_multi_getcontent($h),true);foreach($headers[$i] as $line){if(preg_match('/^Set-Cookie: ([^=]+)=([^;]*)/i',$line,$m)){$cookies[$user][$m[1]]=$m[2];}}if(isset($body['data']['csrf'])){$csrf[$user]=$body['data']['csrf'];}$out[]=['status'=>curl_getinfo($h,CURLINFO_RESPONSE_CODE),'ms'=>curl_getinfo($h,CURLINFO_TOTAL_TIME)*1000,'body'=>$body];curl_multi_remove_handle($multi,$h);curl_close($h);}curl_multi_close($multi);return $out;
}
try{
    for($i=0;$i<8;++$i){$pipes=[];$p=proc_open([PHP_BINARY,'-S','127.0.0.1:'.(33400+$i),'-t',$root.'/public',$root.'/tests/identity-router.php'],[0=>['pipe','r'],1=>['file',$root.'/storage/review-http.stdout','a'],2=>['file',$root.'/storage/review-http.stderr','a']],$pipes,$root,$env);fclose($pipes[0]);$servers[]=$p;}
    for($i=0;$i<8;++$i){for($retry=0;$retry<30;++$retry){$r=batch([['server'=>$i,'user'=>$i,'path'=>'/api/v1/client/identity/bootstrap']])[0];if($r['status']===200){break;}usleep(100000);}foreach([['login',['email'=>$users[$i]['email'],'password'=>$users[$i]['password']]],['step-up',['password'=>$users[$i]['password'],'code'=>'']]] as [$action,$data]){$r=batch([['server'=>$i,'user'=>$i,'path'=>'/api/v1/client/identity/'.$action,'data'=>$data]])[0];if($r['status']!==200){throw new RuntimeException('Load authentication failed: '.$r['status']);}}}
    $runs=[];foreach([1,4,8] as $concurrency){foreach(['different','same'] as $scope){$times=['prepare'=>[],'execute'=>[]];$counts=[];for($round=0;$round<5;++$round){$requests=[];for($i=0;$i<$concurrency;++$i){$requests[]=['server'=>$i,'user'=>$scope==='same'?0:$i,'path'=>'/api/v1/client/commerce/prepare','data'=>['action'=>'attempt-create','payload'=>['minor'=>'10']]];}$prepared=batch($requests);$execute=[];foreach($prepared as $i=>$r){$times['prepare'][]=$r['ms'];$counts['prepare_'.$r['status']]=($counts['prepare_'.$r['status']]??0)+1;if($r['status']===200){$request=$requests[$i];$request['path']='/api/v1/client/commerce/execute';$request['data']['confirmation']=['id'=>$r['body']['data']['id'],'accepted'=>true];$execute[]=$request;}}foreach(batch($execute) as $r){$times['execute'][]=$r['ms'];$counts['execute_'.$r['status']]=($counts['execute_'.$r['status']]??0)+1;}}$metrics=[];foreach($times as $phase=>$samples){sort($samples);$metrics[$phase]=['requests'=>count($samples),'p50_ms'=>$samples[(int)floor((count($samples)-1)*.5)]??null,'p95_ms'=>$samples[(int)floor((count($samples)-1)*.95)]??null,'max_ms'=>$samples?max($samples):null];}$runs[]=['workers'=>$concurrency,'scope'=>$scope,'counts'=>$counts,'latency'=>$metrics];}}
    echo json_encode(['database'=>$db->execute('SELECT VERSION()')->fetchColumn(),'transport'=>'loopback HTTP; 8 independent PHP servers; real auth/CSRF/step-up/confirmations; 5 rounds per workload','runs'=>$runs],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR)."\n";
}finally{foreach($servers as $p){proc_terminate($p);proc_close($p);}}
